:root{
  --bg:#1b1b2f;
  --panel:#2e2e4a;
  --accent:#f6c945;
  --accent2:#4ec9b0;
  --text:#f2f2f7;
  --danger:#e06c75;
  --font:"Courier New",Courier,monospace;
}
*{box-sizing:border-box}
body{
  margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;
  padding:24px 16px;background:var(--bg);color:var(--text);font-family:var(--font);font-size:16px;
  background-image:linear-gradient(45deg,#22223a 25%,transparent 25%),linear-gradient(-45deg,#22223a 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#22223a 75%),linear-gradient(-45deg,transparent 75%,#22223a 75%);
  background-size:32px 32px;background-position:0 0,0 16px,16px -16px,-16px 0;
}
.card{
  width:100%;max-width:480px;background:var(--panel);padding:28px 24px;
  border:4px solid var(--accent);box-shadow:8px 8px 0 #0e0e1a;
}
h1{margin:0 0 16px;font-size:24px;letter-spacing:2px;color:var(--accent);text-align:center}
.stats{display:flex;justify-content:space-between;gap:12px;margin:0 0 20px;font-size:16px}
.stats strong{color:var(--accent2)}
.add-row{display:flex;gap:8px;margin-bottom:20px}
input[type=text]{
  flex:1;min-width:0;padding:12px;font-family:var(--font);font-size:16px;
  background:#1b1b2f;color:var(--text);border:3px solid #55557a;outline:none;
}
input[type=text]:focus{border-color:var(--accent2);box-shadow:0 0 0 3px rgba(78,201,176,.35)}
button{
  font-family:var(--font);font-size:16px;cursor:pointer;border:3px solid #0e0e1a;
  padding:12px 16px;background:var(--accent);color:#1b1b2f;font-weight:bold;
  box-shadow:3px 3px 0 #0e0e1a;transition:transform .05s;
}
button:hover{background:#ffd966}
button:active{transform:translate(3px,3px);box-shadow:none}
button:focus-visible{outline:3px solid var(--accent2);outline-offset:2px}
.todo-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.todo-item{
  display:flex;align-items:center;gap:10px;padding:10px 12px;background:#242440;
  border:2px solid #55557a;flex-wrap:wrap;
}
.todo-item.done .todo-text{text-decoration:line-through;opacity:.55;color:var(--accent2)}
.todo-text{flex:1;min-width:0;word-break:break-word;font-size:16px}
.todo-item input[type=checkbox]{width:20px;height:20px;accent-color:var(--accent2);cursor:pointer}
.todo-item input[type=checkbox]:focus-visible{outline:3px solid var(--accent2);outline-offset:2px}
.delete-btn{background:var(--danger);color:#fff;padding:6px 10px;font-size:16px}
.delete-btn:hover{background:#f08a92}
.empty{text-align:center;color:#8888aa;font-size:16px;margin:12px 0 0}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0}
@media(max-width:400px){.card{padding:20px 14px}h1{font-size:20px}}

(function () {
  'use strict';
  var list = document.getElementById('todo-list');
  var input = document.getElementById('todo-input');
  var form = document.getElementById('todo-form');
  var totalEl = document.getElementById('todo-total');
  var remainingEl = document.getElementById('remaining');
  var emptyMsg = document.getElementById('empty-msg');
  var tasks = [];
  var nextId = 1;

  function updateCounts() {
    totalEl.textContent = String(tasks.length);
    var remaining = tasks.filter(function (t) { return !t.done; }).length;
    remainingEl.textContent = String(remaining);
    emptyMsg.style.display = tasks.length ? 'none' : 'block';
  }

  function addTask(text) {
    var id = nextId++;
    var task = { id: id, text: text, done: false };
    tasks.push(task);

    var li = document.createElement('li');
    li.className = 'todo-item';
    li.dataset.id = String(id);

    var check = document.createElement('input');
    check.type = 'checkbox';
    check.id = 'todo-check-' + id;
    check.setAttribute('aria-label', 'Mark task done: ' + text);

    var span = document.createElement('span');
    span.className = 'todo-text';
    span.id = 'todo-text-' + id;
    span.textContent = text;

    var del = document.createElement('button');
    del.type = 'button';
    del.className = 'delete-btn';
    del.id = 'todo-delete-' + id;
    del.textContent = 'X';
    del.setAttribute('aria-label', 'Delete task: ' + text);

    check.addEventListener('change', function () {
      task.done = check.checked;
      li.classList.toggle('done', task.done);
      updateCounts();
    });

    del.addEventListener('click', function () {
      tasks = tasks.filter(function (t) { return t.id !== id; });
      li.remove();
      updateCounts();
    });

    li.appendChild(check);
    li.appendChild(span);
    li.appendChild(del);
    list.appendChild(li);
    updateCounts();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) { input.value = ''; return; }
    addTask(text);
    input.value = '';
    input.focus();
  });

  updateCounts();
})();
